let language='en';
try{language=localStorage.getItem('portfolio-language')==='zh'?'zh':'en'}catch{}
const copy={en:{label:'Portfolio / Xin(Robynn)Shen',title:'Selected work.',intro:'Creative direction, image-making & interactive experiences.',role:'My contribution',visit:'Explore project ↗',video:'Watch films',more:'View more images',demo:'Project walkthrough',controls:'Press play to watch',footer:'Creative projects & interactive experiments.',top:'Back to top ↑',count:'projects'},zh:{label:'作品集 / Xin(Robynn)Shen',title:'精选作品。',intro:'创意设计、影像与互动体验。',role:'我的职责',visit:'在线体验 ↗',video:'观看项目视频',more:'查看更多图片',demo:'项目操作演示',controls:'点击播放观看',footer:'创意项目与互动探索。',top:'回到顶部 ↑',count:'个项目'}};
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tr=s=>typeof s==='object'?(s[language]||s.en||''):s;
function dimensions(src){const d=PORTFOLIO.dimensions?.[src];return d?`width="${d[0]}" height="${d[1]}"`:''}
function imageRows(rows,p){return (rows||[]).map((row,i)=>`<div class="image-row ${row.length===3?'three':''} ${i===0&&p.id==='ballerine'?'lead':''}">${row.map((src,j)=>`<figure><img ${dimensions(typeof src==='object'?src.src:src)} src="${escapeHTML(typeof src==='object'?src.src:src)}" alt="${escapeHTML(tr(p.title))} — ${language==='zh'?'作品图':'project image'} ${i*3+j+1}" loading="${p.id==='ballerine'&&i===0?'eager':'lazy'}" decoding="async"></figure>`).join('')}</div>`).join('')}
function mediaSources(v){return (v.webm?`<source src="${escapeHTML(v.webm)}" type="video/webm">`:'')+`<source src="${escapeHTML(v.src)}" type="video/mp4">`}
function videoHTML(v,p){return `<figure class="video-item"><video ${dimensions(v.poster)} controls playsinline preload="none" poster="${escapeHTML(v.poster)}" aria-label="${escapeHTML(tr(v.title)||tr(p.title))}">${mediaSources(v)}</video><figcaption>${escapeHTML(tr(v.title)||tr(p.title))}</figcaption></figure>`}
function render(){const t=copy[language];document.documentElement.lang=language==='zh'?'zh':'en';document.title=`Xin(Robynn)Shen — ${language==='zh'?'精选作品':'Selected Work'}`;document.querySelector('meta[name=description]').content=language==='zh'?'Xin(Robynn)Shen 的创意、摄影与互动作品集。':'Selected creative, photographic and interactive work by Xin(Robynn)Shen.';document.querySelector('.skip-link').textContent=language==='zh'?'跳至作品':'Skip to work';document.querySelector('#intro-label').textContent=t.label;document.querySelector('#page-title').textContent=t.title;document.querySelector('#intro-description').textContent=t.intro;document.querySelector('#footer-text').textContent=t.footer;document.querySelector('#back-top').textContent=t.top;document.querySelectorAll('[data-language]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.language===language)));let index=0;const categories=PORTFOLIO.categories.filter(c=>c.projects.length);document.querySelector('#navigation').innerHTML=categories.map(c=>`<a href="#${c.id}">${escapeHTML(c[language])}</a>`).join('');document.querySelector('#work').innerHTML=categories.map(c=>`<section class="category ${c.id}" id="${c.id}" aria-label="${escapeHTML(c[language])}"><h2 class="category-heading"><span>${escapeHTML(c[language])}</span><span>${String(c.projects.length).padStart(2,'0')} ${t.count}</span></h2>${c.projects.map(p=>{index++;return `<article class="project" id="${p.id}"><div class="project-strip"><span><span class="number">${String(index).padStart(2,'0')}</span>${language==='zh'?'项目':'Project'}</span><span>${escapeHTML(p.client||tr(p.title))}</span><span class="discipline">${escapeHTML(tr(p.discipline))}</span></div><div class="project-body"><div class="project-info"><h2>${escapeHTML(tr(p.title))}</h2><p class="project-date">${escapeHTML(tr(p.date))}</p><p class="description">${escapeHTML(tr(p.description))}</p>${tr(p.role)?`<div class="role-block"><p class="role-label">${t.role}</p><p class="role">${escapeHTML(tr(p.role))}</p></div>`:''}${p.metrics?`<p class="metrics">${escapeHTML(tr(p.metrics))}</p>`:''}${p.url?`<a class="project-link" href="${escapeHTML(p.url)}" target="_blank" rel="noopener noreferrer">${t.visit}</a>`:''}</div><div class="gallery">${p.demo?`<video ${dimensions(p.demo.poster)} class="demo-video" controls playsinline preload="none" poster="${escapeHTML(p.demo.poster)}" aria-label="${escapeHTML(tr(p.title))}">${mediaSources(p.demo)}</video><div class="media-note"><span>${t.demo}</span><span>${t.controls}</span></div>`:''}${imageRows(p.rows,p)}${p.extraRows?.length?`<details class="more-media"><summary>${t.more}</summary>${imageRows(p.extraRows,p)}</details>`:''}${p.videos?.length?`<details class="more-media"><summary>${t.video}${p.videos.length>1?' ('+p.videos.length+')':''}</summary><div class="video-grid ${p.portrait?'portrait':''} ${p.videos.length===1?'single':''}">${p.videos.map(v=>videoHTML(v,p)).join('')}</div></details>`:''}</div></div></article>`}).join('')}</section>`).join('')}
document.querySelectorAll('[data-language]').forEach(button=>button.addEventListener('click',()=>{language=button.dataset.language;try{localStorage.setItem('portfolio-language',language)}catch{}render()}));render();

document.addEventListener("play",event=>{if(event.target.tagName==="VIDEO")document.querySelectorAll("video").forEach(video=>{if(video!==event.target&&!video.paused)video.pause()})},true);
document.addEventListener("toggle",event=>{if(event.target.tagName==="DETAILS"&&!event.target.open)event.target.querySelectorAll("video").forEach(video=>{if(!video.paused)video.pause()})},true);
